    match outcome {
        Ok(mut members) => {
            members.insert("ok".into(), true.into());
            Value::Object(members)
        }
        Err(error) => json!({
            "ok": false,
            "error": { "code": error.code.as_str(), "message": error.message },
        }),
    }
}
